import 'package:firebase_auth/firebase_auth.dart';
import 'package:flutter/material.dart';
import '../../../services/creator/creator_repository.dart';
import '../../../core/models/creator.dart';
import '../../messenger/presentation/messenger_screen.dart';

class AurenAURENCreatorStudioScreen extends StatelessWidget{const AurenAURENCreatorStudioScreen({super.key});@override Widget build(BuildContext context){final uid=FirebaseAuth.instance.currentUser?.uid;if(uid==null)return const Scaffold(body:Center(child:Text('سجّل الدخول لإنشاء وإدارة المحتوى.')));final repo=CreatorRepository();return Scaffold(appBar:AppBar(title:const Text('AUREN Creator Studio'),actions:[IconButton(icon:const Icon(Icons.auto_awesome),onPressed:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>const MessengerScreen(initialPrompt:'ساعدني أطور فكرة محتوى، عنوان، وصف، وخطة نشر مناسبة لجمهوري.'))))],floatingActionButton:FloatingActionButton.extended(onPressed:()=>_edit(context,repo,uid),icon:const Icon(Icons.add),label:const Text('Create')),body:StreamBuilder<List<AurenCreatorDraft>>(stream:repo.watchDrafts(uid),builder:(context,s){if(s.hasError)return Center(child:Text('تعذر تحميل المسودات: '+s.error.toString()));if(s.connectionState==ConnectionState.waiting)return const Center(child:CircularProgressIndicator());final drafts=s.data??const <AurenCreatorDraft>[];return ListView(padding:const EdgeInsets.all(16),children:[const ListTile(contentPadding:EdgeInsets.zero,leading:Icon(Icons.auto_awesome,size:34),title:Text('Creator Studio',style:TextStyle(fontSize:22,fontWeight:FontWeight.bold)),subtitle:Text('أنشئ، عدّل، انشر، وخلي AUREN يساعدك.')),if(drafts.isEmpty)const Card(child:Padding(padding:EdgeInsets.all(16),child:Text('ما عندك مسودات. ابدأ بأول فكرة.'))),...drafts.map((d)=>Card(child:ListTile(title:Text(d.title),subtitle:Text(d.status+' • '+d.body),isThreeLine:true,trailing:PopupMenuButton<String>(onSelected:(v)async{if(v=='publish')await repo.publish(d.id);if(v=='edit'&&context.mounted)await _edit(context,repo,uid,draft:d);},itemBuilder:(_)=>[if(d.status!='published')const PopupMenuItem(value:'publish',child:Text('Publish')),const PopupMenuItem(value:'edit',child:Text('Edit'))]),onTap:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>MessengerScreen(initialPrompt:'طوّر لي المحتوى التالي واجعله مناسباً للنشر:\n'+d.title+'\n'+d.body)))))])}));}
Future<void> _edit(BuildContext context,CreatorRepository repo,String uid,{AurenCreatorDraft? draft})async{final title=TextEditingController(text:draft?.title??''),body=TextEditingController(text:draft?.body??'');final ok=await showDialog<bool>(context:context,builder:(c)=>AlertDialog(title:Text(draft==null?'Create Draft':'Edit Draft'),content:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:title,decoration:const InputDecoration(labelText:'Title')),TextField(controller:body,maxLines:5,decoration:const InputDecoration(labelText:'Content'))]),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(c,true),child:const Text('Save'))]));if(ok==true&&title.text.trim().isNotEmpty&&body.text.trim().isNotEmpty){if(draft==null)await repo.createDraft(uid:uid,title:title.text,body:body.text);else await repo.updateDraft(draft.id,title.text,body.text);}}
}